head.script:
scwin.onpageload = function () {
	scwin.unitTest();
};

/**
 * GridView 'grd_exam1'의 'customType' 컬럼의 'typeGetter' 속성에 설정된 메소드
 * 동적으로 셀의 'inputType'을 설정
 */
scwin.getCustomType = function (info) {
    let rowIndex = info.rowIndex;
    let colIndex = info.colIndex;
    let returnInfo = {
        options: {
            readOnly: "false",
            viewType: "default",
            chooseOption: "false"
        }
    };

    let _inputType = dlt_exam.getCellData(rowIndex, "inputType");

    console.log(info);

    switch (_inputType) {
        case "autoComplete":
            returnInfo.itemSet = {
                nodeset: "data:dlt_code",
                label: "codeName",
                value: "code"
            };
            returnInfo.options.viewType = "icon";
            returnInfo.options.chooseOption = "true";
            break;
        case "button":
            break;
        case "calendar":
            returnInfo.options.viewType = "icon";
            break;
        case "checkbox":
            returnInfo.options.checkboxLabel = "checkbox";
            returnInfo.options.valueType = "other";
            returnInfo.options.trueValue = "Y";
            returnInfo.options.falseValue = "N";
            break;
        case "checkcombobox":
            returnInfo.itemSet = {
                nodeset: "data:dlt_code",
                label: "codeName",
                value: "code"
            };
            returnInfo.options.viewType = "icon";
            returnInfo.options.chooseOption = "true";
            break;
        case "image":
            break;
        case "link":
            break;
        case "radio":
            returnInfo.options.checkboxLabel = "radio";
            returnInfo.options.valueType = "other";
            returnInfo.options.trueValue = "Y";
            returnInfo.options.falseValue = "N";
            break;
        case "secret":
            break;
        case "select":
            returnInfo.itemSet = {
                nodeset: "data:dlt_code",
                label: "codeName",
                value: "code"
            };
            returnInfo.options.viewType = "icon";
            returnInfo.options.chooseOption = "true";
            break;
        case "spinner":
            returnInfo.options.viewType = "icon";
            break;
        case "textarea":
            break;
        case "textImage":
            returnInfo.options.viewType = "icon";
            returnInfo.options.imageSrc = "/img/icons_search_type2.png";
            returnInfo.options.imageHeight = "20";
            returnInfo.options.readOnly = "true";
            break;
        case "text":
        default:
            break;
    }

    returnInfo.id = "dynamic_" + _inputType + "_" + rowIndex + "_" + colIndex;
    returnInfo.inputType = _inputType;

    console.log("return: \n", JSON.stringify(returnInfo));

    return returnInfo;
};

/**
 * GridView 'grd_exam1'의 'onafteredit' 이벤트 핸들러. 
 * 셀 입력 후 발생
 */
scwin.grd_exam1_onafteredit = function (row, col, value) {
    let colId = this.getColumnID(col);

    console.log("scwin.grd_exam1_onafteredit", arguments);

    if (colId != "inputType") { return; }

    let cellData = "";
    switch (value) {
        case "autoComplete":
            cellData = "03";
            break;
        case "button":
            cellData = "button";
            break;
        case "calendar":
            cellData = "20241231";
            break;
        case "checkbox":
            cellData = "Y";
            break;
        case "checkcombobox":
            cellData = "03";
            break;
        case "image":
            cellData = "/img/btn_sub_setting.png";
            break;
        case "link":
            cellData = "link";
            break;
        case "radio":
            cellData = "N";
            break;
        case "secret":
            cellData = "secret";
            break;
        case "select":
            cellData = "03";
            break;
        case "spinner":
            cellData = "12";
            break;
        case "textarea":
            cellData = "textarea";
            break;
        case "textImage":
            cellData = "textImage";
            break;
        case "text":
        default:
            cellData = "text";
            break;
    }

    dlt_exam.setCellData(row, "customType", cellData);
};

scwin.checkVal = function() {
	var retVal;

	// 확인하고자 하는 ID
	// const elementId = "G_mf_grd_exam1___spinner_dynamic_spinner_0_1_upButton";
	const elementId = "G_"+$p.id+"grd_exam1___spinner_dynamic_spinner_0_1_upButton";

	// 해당 ID를 가진 요소를 찾기
	const element = WebSquare.wUnit.getDomById(elementId);

	// 요소가 존재하는지 확인
	if (element) {
		retVal = false;
	} else {
		retVal = true;
	}
	debugger;
	return retVal;
};

scwin.unitTest = function() {
	//Unit 
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_exam1_cell_0_0').click();");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_grd_exam1___selectbox_inputType_itemTable_1').click();");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
};
